import React, { useMemo } from "react";
import { CheckCircle } from "lucide-react";

/*
  TRUE TREE RENDERER
  - SVG based
  - children centered
  - real connectors
*/

const NODE_RADIUS = 26;
const LEVEL_GAP = 120;
const SIBLING_GAP = 120;

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {
  
  // ================= DATA =================

  const hybrid = [
    { title: "Ephemeral", sub: "X25519", children: ["Generate", "Exchange"] },
    { title: "Encapsulate", sub: "Kyber", children: ["Secret", "Cipher"] },
    { title: "HKDF", sub: "SHA-256", children: ["Salt", "Expand"] },
    { title: "AES", sub: "GCM", children: ["Encrypt", "Tag"] },
    { title: "Upload", sub: "MinIO", children: ["Pack", "Store"] },
  ];

  const rsa = [
    { title: "Keypair", sub: "RSA", children: ["Public", "Private"] },
    { title: "Padding", sub: "OAEP", children: ["Prepare"] },
    { title: "Encrypt", sub: "ModExp", children: ["Cipher"] },
    { title: "Blob", sub: "Meta", children: ["Headers"] },
    { title: "Upload", sub: "MinIO", children: ["Store"] },
  ];

  const phases = mode === "hybrid" ? hybrid : rsa;

  const color = mode === "hybrid" ? "#00ff9d" : "#a855f7";

  // ================= LAYOUT =================

  const layout = useMemo(() => {
    const nodes = [];
    const edges = [];

    let x = 80;

    phases.forEach((p, i) => {
      const y = 120;

      nodes.push({ id: `p-${i}`, x, y, parent: null, phase: i });

      const branchUp = i % 2 === 1;

      p.children.forEach((c, k) => {
        const offset =
          (k - (p.children.length - 1) / 2) * SIBLING_GAP;

        const cx = x + offset;
        const cy = branchUp ? y - LEVEL_GAP : y + LEVEL_GAP;

        nodes.push({ id: `c-${i}-${k}`, x: cx, y: cy, child: true });

        edges.push({
          from: `p-${i}`,
          to: `c-${i}-${k}`,
        });
      });

      if (i > 0) {
        edges.push({ from: `p-${i - 1}`, to: `p-${i}` });
      }

      x += 200;
    });

    return { nodes, edges };
  }, [phases]);

  // ================= RENDER =================

  return (
    <div className="bg-black/40 border border-scifi-border rounded-xl overflow-auto">
      <svg width={1200} height={300}>

        {/* EDGES */}
        {layout.edges.map((e, i) => {
          const a = layout.nodes.find(n => n.id === e.from);
          const b = layout.nodes.find(n => n.id === e.to);

          const active = currentStep > parseInt(e.from.split("-")[1]);

          return (
            <line
              key={i}
              x1={a.x}
              y1={a.y}
              x2={b.x}
              y2={b.y}
              stroke={active ? color : "#333"}
              strokeWidth="2"
            />
          );
        })}

        {/* NODES */}
        {layout.nodes.map((n, i) => {
          const active = n.phase !== undefined && currentStep >= n.phase + 1;

          return (
            <g key={i}>
              <circle
                cx={n.x}
                cy={n.y}
                r={NODE_RADIUS}
                fill="#0b0f14"
                stroke={active ? color : "#444"}
                strokeWidth="2"
              />
              {active && (
                <foreignObject
                  x={n.x - 10}
                  y={n.y - 10}
                  width={20}
                  height={20}
                >
                  <CheckCircle size={18} color={color} />
                </foreignObject>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
};

export default CryptoFlow;
